arguments.command:
cd /tmp/sv-9434d671b1fc44c78cb541ad93377736

# Extract all FUNC symbols with addresses, sorted by address
readelf -Ws libmonosgen-2.0.so 2>/dev/null | awk '$4 == "FUNC" && $2 != "0000000000000000" {print $2, $3, $8}' | sort > /tmp/mono_syms.txt

# Now find the function for each PC offset
python3 << 'EOF'
addrs = [0x222098, 0x2241ac, 0x1abc80, 0x1abd14, 0x16dfa4, 0x16db6c, 0x16de04]

# Read symbols
syms = []
with open('/tmp/mono_syms.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            size = int(parts[1])
            name = parts[2]
            syms.append((addr, size, name))

syms.sort()

def find_func(pc):
    best = None
    for addr, size, name in syms:
        if addr <= pc:
            best = (addr, size, name)
        else:
            break
    if best:
        addr, size, name = best
        if pc < addr + size or size == 0:
            return f"{name}+0x{pc - addr:x}"
    return "???"

for i, pc in enumerate(addrs):
    func = find_func(pc)
    print(f"  #0{i+1} pc 0x{pc:08x}  libmonosgen-2.0.so ({func})")
EOF

